contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 adminSeed, string calldata description) public payable {
        address caller = address(this);
        bool adminBefore = c.isAdmin(caller); if (__ESBMC_reverted()) return;
        address randomAddr = address(uint160(uint256(keccak256(abi.encodePacked(adminSeed)))));
        bool isRandomAdmin = c.isAdmin(randomAddr); if (__ESBMC_reverted()) return;
        require(!(isRandomAdmin && randomAddr != caller), "seed collision");

        bool reverted;
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == !adminBefore);
    }

    receive() external payable {}
}

