pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(uint256 adminSeed, string memory description) internal {
        address caller = address(this);
        bool adminBefore;
        try c.isAdmin(caller) returns (bool __r) { adminBefore = __r; } catch { return; }
        address randomAddr = address(uint160(uint256(keccak256(abi.encodePacked(adminSeed)))));
        bool isRandomAdmin;
        try c.isAdmin(randomAddr) returns (bool __r) { isRandomAdmin = __r; } catch { return; }
        vm.assume(!(isRandomAdmin && randomAddr != caller));
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == !adminBefore);
    }

    function testFuzz_run(uint256 adminSeed, string memory description) public {
        _run(adminSeed, description);
    }

    receive() external payable {}
}
